"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3344],{92772:e=>{e.exports=JSON.parse('{"functions":[{"name":"bind","desc":"Scales every matching descendant of `root` now, on every `root` resize, and\\nas new descendants are added. `referenceHeight` is `root`\'s pixel height at\\nthe resolution the GUI was authored for. Returns a Janitor owning the\\nconnections; a GUI that lives for the whole session can ignore it.","params":[{"name":"root","desc":"","lua_type":"GuiObject"},{"name":"referenceHeight","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"Janitor.Janitor\\n"}],"function_type":"static","source":{"line":58,"path":"src/ReplicatedStorage/SharedModules/Gui/ResponsiveScale.luau"}}],"properties":[],"types":[],"name":"ResponsiveScale","desc":"Shrinks a Studio-authored GUI\'s pixel-valued properties in step with the\\nGUI\'s on-screen height, so a layout authored at desktop resolution stays\\nproportional on a phone. Scale-sized frames already shrink on their own;\\nwhat does not is `UITextSizeConstraint.MinTextSize`/`MaxTextSize` (a\\nMin authored for 1080p forces text bigger than its box on a 360p phone)\\nand `ScrollingFrame.ScrollBarThickness`.\\n\\n`factor = clamp(root.AbsoluteSize.Y / referenceHeight, 0, 1)` \u2014 desktop at\\nthe reference height keeps the authored values exactly; smaller screens\\nscale them down. Never scales up.\\n\\nEach instance\'s authored value is stored once as an attribute\\n(`Authored<Property>`) and every rescale reads from it, so rescales never\\ncompound and a runtime `Clone()` of an already-scaled element (grid items,\\ndropdown rows) carries the authored value with it.","realm":["Client"],"source":{"line":22,"path":"src/ReplicatedStorage/SharedModules/Gui/ResponsiveScale.luau"}}')}}]);